import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const read=p=>readFileSync(new URL('../'+p,import.meta.url),'utf8');
const css=read('studio-sidebar-modern.css'),vision=read('studio-vision.js');
const html=read('index.php'),sw=read('sw.js'),js=read('script.js');
const start=css.indexOf('/* 2387: Keep the phone navigation');
assert.ok(start>0);
const patch=css.slice(start);
assert.match(patch,/@media \(max-width:768px\)/);
assert.match(patch,/\.vision-ui\.showcase-wave-only>\.vision-bottom-nav,/);
assert.match(patch,/\.vision-ui\.vision-player-expanded>\.vision-bottom-nav \{/);
assert.match(patch,/display:grid!important;visibility:visible!important;opacity:1!important/);
assert.match(patch,/z-index:240!important/);
assert.match(patch,/padding-bottom:calc\(91px \+ env\(safe-area-inset-bottom,0px\)\)!important/);
assert.match(vision,/const mobileBrand = el\('div', 'vision-top-brand'\)/);
assert.doesNotMatch(vision,/activateBrand\(/);
assert.match(vision,/root\.classList\.remove\('showcase-wave-only'\);\s*document\.getElementById\('showcase-menu-toggle'\)\?\.click\(\)/);
assert.match(vision,/window\.playNext\?\.\(\)/);
assert.match(vision,/window\.playPrev\?\.\(\)/);
assert.match(html,/studio-vision\.js\?v=12/);
assert.match(html,/studio-sidebar-modern\.css\?v=11/);
assert.match(sw,/studio-vision\.js\?v=12/);
assert.match(sw,/studio-sidebar-modern\.css\?v=11/);
assert.match(html,/script\.js\?v=2389/);
assert.match(sw,/dagstudio-player-shell-v2406/);
assert.match(js,/WEB_BUILD_LABEL = '2389'/);
console.log('MOBILE_FULLSCREEN_BOTTOM_MENU_VISIBLE_AND_BRANDS_NOT_CLICKABLE_OK');
